typedef int int32;
typedef float rational_t;
class PhysicsObjectClass;
typedef PhysicsObjectClass *PhysicsObjectClassPtr;
typedef void (*OdeDerivFunc)(PhysicsObjectClass *, float, float *, float *);
class vector3d
{
public:
  rational_t x, y, z;
  vector3d() {}
  vector3d(rational_t _x, rational_t _y, rational_t _z) : x(_x), y(_y), z(_z) {}
};
class po
{
public:
  float m[16] __attribute__((aligned(16)));
};
extern const po po_identity_matrix;
class OdeSolverClass
{
public:
  OdeSolverClass() { dim = 0; stepSize = 0.0f; fnDerivFunc = 0; }
  virtual ~OdeSolverClass() {}
  virtual int32 Init(int, float, OdeDerivFunc) = 0;
  virtual int32 Terminate() = 0;
  virtual int32 Update(PhysicsObjectClass *, float, float *, float *, float *) = 0;
  virtual void SetStepSize(float dt) { stepSize = dt; }
protected:
  int32 dim;
  float stepSize;
  OdeDerivFunc fnDerivFunc;
};
class RungeKuttaClass : public OdeSolverClass
{
public:
  RungeKuttaClass() { temp1 = temp2 = temp3 = temp4 = xtemp = 0; }
  virtual ~RungeKuttaClass() { this->Terminate(); }
  int32 Init(int, float, OdeDerivFunc);
  int32 Terminate();
  int32 Update(PhysicsObjectClass *, float, float *, float *, float *);
  virtual void SetStepSize(float dt) { stepSize = dt; step2 = dt / 2.0f; step6 = dt / 6.0f; }
private:
  float step2, step6;
  float *temp1, *temp2, *temp3, *temp4, *xtemp;
};
class PhysicsObjectClass
{
public:
  PhysicsObjectClass();
  static void DerivFunc(PhysicsObjectClassPtr, float, float *, float *);
  float mass;
  float inverseMass;
  vector3d force;
  vector3d velo;
  vector3d pos;
  po my_po;
  vector3d linMom;
private:
  RungeKuttaClass ode;
};
PhysicsObjectClass::PhysicsObjectClass()
{
  force = vector3d(0, 0, 0);
  velo = vector3d(0, 0, 0);
  pos = vector3d(0, 0, 0);
  my_po = po_identity_matrix;

  mass = 1.0;
  inverseMass = 1.0;

  pos = vector3d(0,0,0);
  linMom = vector3d(0,0,0);

  // init ode
  this->ode.Init(18, 0.1f, PhysicsObjectClass::DerivFunc);
}
